// Throwaway comparison: which laptop workspace hierarchy makes modal guitar practice easiest?
const modes = [
  ['I','Dm(maj7)','D','D melodic minor'], ['II','Em7','E','Dorian ♭2'],
  ['III','Fmaj7#5','F','Lydian augmented'], ['IV','G7','G','Lydian dominant'],
  ['V','A7','A','Mixolydian ♭6'], ['VI','Bm7b5','B','Locrian ♮2'],
  ['VII','C#m7b5','C#','Altered']
];
const names = {A:'Practice desk', B:'Instrument panel', C:'Study workspace'};
const state = {degree:0, workflow:'Guided', playing:false, preset:'Clean guitar', volume:70, position:1, tab:'Score'};
const app = document.querySelector('#app');
function variant(){ const v = new URL(location.href).searchParams.get('variant'); return names[v] ? v : 'A'; }
function changeVariant(delta){ const keys = Object.keys(names); const url = new URL(location.href); url.searchParams.set('variant', keys[(keys.indexOf(variant()) + delta + keys.length) % keys.length]); history.pushState({}, '', url); render(); }
function setup(){return `<div class="setup"><div class="field"><span>Parent scale</span><strong>D jazz melodic minor</strong></div><div class="field"><span>Practice</span><div class="segmented"><button data-workflow="Guided" class="${state.workflow==='Guided'?'active':''}">Guided</button><button data-workflow="Self-guided" class="${state.workflow==='Self-guided'?'active':''}">Self-guided</button></div></div><label class="field">Position <select data-control="position"><option value="1" ${state.position===1?'selected':''}>Position 1 · frets 1–8</option><option value="5" ${state.position===5?'selected':''}>Position 2 · frets 5–12</option></select></label></div>`}
function modeList(){return `<div class="modes">${modes.map((m,i)=>`<button class="mode ${i===state.degree?'active':''}" data-degree="${i}" aria-pressed="${i===state.degree}"><span>${m[0]} · ${m[2]}</span><strong>${m[1]}</strong><span>${m[3]}</span></button>`).join('')}</div>`}
function player(){let m=modes[state.degree];return `<div class="player"><button class="play" data-play>${state.playing?'■ Stop':'▶ Play'}</button><div class="now"><strong>${m[1]}</strong> <span class="muted">· ${m[2]} ${m[3]}</span><div class="noaudio">${state.playing?'SIMULATED PLAYING':'STOPPED'} · NO AUDIO</div></div><label class="field">Preset <select data-control="preset"><option ${state.preset==='Clean guitar'?'selected':''}>Clean guitar</option><option ${state.preset==='Warm keys'?'selected':''}>Warm keys</option><option ${state.preset==='Sine tone'?'selected':''}>Sine tone</option></select></label><label class="field">Volume <input data-control="volume" type="range" min="0" max="100" value="${state.volume}"><span>${state.volume}%</span></label></div>`}
function score(){let m=modes[state.degree];return `<div class="section-head"><div><h2>Score sketch</h2><p class="muted small">${m[2]} ${m[3]} · illustrative notation, not engraving</p></div><span class="eyebrow">Illustrative</span></div><svg class="score" viewBox="0 0 500 155" role="img" aria-label="Illustrative schematic staff, not validated notation"><g stroke="#647168" stroke-width="1">${[42,55,68,81,94].map(y=>`<line x1="20" y1="${y}" x2="480" y2="${y}"/>`).join('')}</g><text x="23" y="87" font-size="58" fill="#d3dcd1">𝄞</text><text x="84" y="76" font-size="22" fill="#d3dcd1">♯</text>${[115,160,205,250,295,340,385,430].map((x,i)=>`<ellipse cx="${x}" cy="${[91,82,74,66,58,50,42,34][i]}" rx="7" ry="5" fill="${i===0?'#91bfe8':'#d3dcd1'}" transform="rotate(-18 ${x} ${[91,82,74,66,58,50,42,34][i]})"/>`).join('')}<text x="112" y="130" fill="#9fac9f" font-size="12">D   E   F   G   A   B   C♯   D</text></svg>`}
function neck(){const pitches=['C','C#','D','D#','E','F','F#','G','G#','A','A#','B'];const scale=['D','E','F','G','A','B','C#'];const strings=[['e',4],['B',11],['G',7],['D',2],['A',9],['E',4]];let root=modes[state.degree][2];return `<div class="section-head"><div><h2>Guitar neck</h2><p class="muted small">Fixed physical position · blue marks ${root}, the modal root</p></div><span class="eyebrow">UNREVIEWED PITCH MAP</span></div><div class="fretboard"><div class="neck">${strings.map(([label,pitch])=>`<div class="string">${label}</div>${Array.from({length:8},(_,i)=>{let n=pitches[(pitch+state.position+i)%12];return `<div>${scale.includes(n)?`<span class="note ${n===root?'root':''}">${n}</span>`:''}</div>`}).join('')}`).join('')}</div><div class="frets"><span></span>${Array.from({length:8},(_,i)=>`<span>${state.position+i}</span>`).join('')}</div></div><div class="legend">STANDARD TUNING · D E F G A B C♯ · NOT VALIDATED CAGED</div>`}
function header(){return `<div class="topline"><div class="brand">● <span>practice</span> / modal lab</div><div class="muted small">THROWAWAY PROTOTYPE · NO AUDIO</div></div>`}
function heading(title,description){return `<div class="heading"><div><div class="eyebrow">Modal practice / D melodic minor</div><h1>${title}</h1><p class="muted">${description}</p></div><div class="muted small">D &nbsp; E &nbsp; F &nbsp; G &nbsp; A &nbsp; B &nbsp; C♯</div></div>`}
function variantA(){return `${heading('Practice desk','Set up, choose a sound, and keep the score and neck in view.')}<div class="panel">${setup()}</div>${modeList()}<div class="panel">${player()}</div><div class="study-grid"><section class="panel">${score()}</section><section class="panel">${neck()}</section></div>`}
function variantB(){let m=modes[state.degree];return `${heading('Instrument panel','Choose a degree, then focus on the sound in front of you.')}<div class="b-layout"><aside class="b-rail"><div class="eyebrow">Degrees / modes</div>${modeList()}</aside><main class="b-main"><div class="panel">${setup()}</div><div class="panel hero" style="margin-top:12px"><div><div class="eyebrow">${m[0]} degree · modal root ${m[2]}</div><div class="hero-chord">${m[1]}</div><h2>${m[2]} ${m[3]}</h2><p class="muted small">From D jazz melodic minor</p>${player()}</div><div class="eyebrow">CURRENT<br>FOCUS</div></div><div class="study-grid"><section class="panel">${score()}</section><section class="panel">${neck()}</section></div></main></div>`}
function variantC(){let m=modes[state.degree];return `${heading('Study workspace','Navigate the harmony on the left; study one surface at a time.')}<div class="c-layout"><aside class="sidebar"><div class="eyebrow">Practice setup</div>${setup()}<div class="eyebrow">Degrees / modes</div>${modeList()}</aside><main class="workspace"><div class="panel">${player()}</div><section class="panel study-panel"><div class="eyebrow">Study surface · ${m[0]} / ${m[1]} / ${m[2]}</div><div class="tabs"><button class="tab ${state.tab==='Score'?'active':''}" data-tab="Score">Score</button><button class="tab ${state.tab==='Neck'?'active':''}" data-tab="Neck">Guitar neck</button></div>${state.tab==='Score'?score():neck()}</section></main></div>`}
function render(){let v=variant(),m=modes[state.degree];app.innerHTML=`<div class="shell">${header()}${({A:variantA,B:variantB,C:variantC})[v]()}<details class="state"><summary>Prototype state</summary><pre>Variant: ${v} — ${names[v]}\nWorkflow: ${state.workflow}\nDegree: ${m[0]} · Chord: ${m[1]} · Modal root: ${m[2]} · Mode: ${m[3]}\nPosition: frets ${state.position}–${state.position+7}\nPlayback: ${state.playing?'simulated playing':'stopped'} (NO AUDIO)\nPreset: ${state.preset} · Volume: ${state.volume}%\nStudy tab: ${state.tab}</pre></details></div>`;document.querySelector('#variant-label').textContent=`${v} — ${names[v]}`;}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.switch)changeVariant(Number(b.dataset.switch));else if(b.dataset.degree!==undefined){state.degree=Number(b.dataset.degree);render()}else if(b.dataset.workflow){state.workflow=b.dataset.workflow;render()}else if(b.hasAttribute('data-play')){state.playing=!state.playing;render()}else if(b.dataset.tab){state.tab=b.dataset.tab;render()}});
document.addEventListener('change',e=>{let key=e.target.dataset.control;if(!key)return;state[key]=key==='position'||key==='volume'?Number(e.target.value):e.target.value;render()});
document.addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight'].includes(e.key)||e.altKey||e.ctrlKey||e.metaKey||e.shiftKey)return;const el=e.target;if(el.closest('input, textarea, select, [contenteditable]:not([contenteditable="false"])'))return;e.preventDefault();changeVariant(e.key==='ArrowLeft'?-1:1)});
window.addEventListener('popstate',render);
if(!['localhost','127.0.0.1','[::1]','::1'].includes(location.hostname))document.querySelector('#switcher').hidden=true;
render();
